customize.liquid.value:
{% render 'customise-control', product: product, block: block, control: 'manual' %}
{% schema %}
{
  "name": "Insignia customization",
  "target": "section",
  "javascript": "insignia-storefront.js",
  "settings": [
    {
      "type": "paragraph",
      "content": "Optional manual placement. Enable the Insignia storefront app embed to replace native purchase controls. The button appears for products with published required customization."
    },
    {
      "type": "text",
      "id": "button_label",
      "label": "Button label",
      "info": "Leave blank to use the storefront language."
    },
    {
      "type": "select",
      "id": "button_style",
      "label": "Button style",
      "default": "auto",
      "options": [
        {
          "value": "auto",
          "label": "Match theme purchase button"
        },
        {
          "value": "primary",
          "label": "Primary"
        },
        {
          "value": "secondary",
          "label": "Secondary"
        }
      ]
    },
    {
      "type": "select",
      "id": "button_width",
      "label": "Button width",
      "default": "theme",
      "options": [
        {
          "value": "theme",
          "label": "Match theme"
        },
        {
          "value": "full",
          "label": "Full width"
        },
        {
          "value": "content",
          "label": "Fit text"
        }
      ]
    },
    {
      "type": "color",
      "id": "button_background",
      "label": "Background override"
    },
    {
      "type": "color",
      "id": "button_color",
      "label": "Text color override"
    },
    {
      "type": "checkbox",
      "id": "override_radius",
      "label": "Override corner radius",
      "default": false
    },
    {
      "type": "range",
      "id": "button_radius",
      "label": "Corner radius",
      "min": 0,
      "max": 40,
      "step": 1,
      "unit": "px",
      "default": 6
    },
    {
      "type": "checkbox",
      "id": "override_border",
      "label": "Override border width",
      "default": false
    },
    {
      "type": "range",
      "id": "button_border_width",
      "label": "Border width",
      "min": 0,
      "max": 6,
      "step": 1,
      "unit": "px",
      "default": 1
    },
    {
      "type": "color",
      "id": "button_border_color",
      "label": "Border color override"
    },
    {
      "type": "range",
      "id": "button_spacing",
      "label": "Vertical spacing",
      "min": 0,
      "max": 40,
      "step": 1,
      "unit": "px",
      "default": 0
    },
    {
      "type": "text",
      "id": "proxy_prefix",
      "label": "App proxy prefix",
      "default": "insignia"
    }
  ]
}
{% endschema %}

customise-control.liquid.value:
{%- liquid
  assign policy = product.metafields['$app'].insignia_policy_v2.value | split: ':'
  assign generation = shop.metafields['$app'].insignia_public_config_v2.value.generationHex
  assign required = false
  if generation != blank and policy.size == 3 and policy[0] == generation and policy[2] == 'required'
    assign required = true
  endif
  assign control_tag = 'insignia-buyer'
  if control == 'automatic'
    assign control_tag = 'insignia-theme-integration'
  endif
  assign default_label = 'insignia.customise' | t
-%}
{%- if control == 'automatic' or required -%}
  <{{ control_tag }}
    product-id="{{ product.id }}"
    {% if control == 'automatic' %}
      variant-ids="{{ product.variants | map: 'id' | join: ',' }}"
      auto-placement="{{ block.settings.auto_placement }}"
    {% else %}
      {{ block.shopify_attributes }}
    {% endif %}
    {% if required %}known-required{% endif %}
    proxy-base="{{ routes.root_url }}apps/{{ block.settings.proxy_prefix | escape }}"
    cart-root="{{ routes.root_url }}" country="{{ localization.country.iso_code }}" market-id="{{ localization.market.id }}"
    language="{{ request.locale.iso_code | escape }}" store-name="{{ shop.name | escape }}"
    trigger-label="{{ block.settings.button_label | default: default_label | escape }}"
    button-style="{{ block.settings.button_style | escape }}"
    button-width="{{ block.settings.button_width | escape }}"
    {% if block.settings.button_background != blank %}button-background="{{ block.settings.button_background | escape }}"{% endif %}
    {% if block.settings.button_color != blank %}button-color="{{ block.settings.button_color | escape }}"{% endif %}
    {% if block.settings.override_radius %}button-radius="{{ block.settings.button_radius }}px"{% endif %}
    {% if block.settings.override_border %}button-border-width="{{ block.settings.button_border_width }}px"{% endif %}
    {% if block.settings.button_border_color != blank %}button-border-color="{{ block.settings.button_border_color | escape }}"{% endif %}
    {% if block.settings.button_spacing > 0 %}button-spacing="{{ block.settings.button_spacing }}px"{% endif %}
  ></{{ control_tag }}>
{%- elsif request.design_mode -%}
  <p {{ block.shopify_attributes }}>Publish required customization for this product to show Customise.</p>
{%- endif -%}

targets.input_query:
query CartTransformRunInput {
  cart {
    lines {
      id
      quantity
      line: attribute(key: "_insignia_line_v3") { value }
      legacy: attribute(key: "_insignia_member_v2") { value }
      cost { amountPerQuantity { currencyCode } }
      sellingPlanAllocation { sellingPlan { id } }
      merchandise {
        __typename
        ... on ProductVariant {
          id
          product {
            id
            registration: metafield(key: "insignia_registration_v2") { value }
            policy: metafield(key: "insignia_policy_v2") { value }
          }
        }
      }
    }
  }
  localization { country { isoCode } market { id } }
  shop {
    localTime { date }
    publicConfig: metafield(key: "insignia_public_config_v2") { value }
  }
}

query Input {
  buyerJourney { step }
  cart {
    lines {
      id
      quantity
      line: attribute(key: "_insignia_line_v3") { value }
      legacy: attribute(key: "_insignia_member_v2") { value }
      cost {
        amountPerQuantity { currencyCode }
        subtotalAmount { amount currencyCode }
      }
      sellingPlanAllocation { sellingPlan { id } }
      merchandise {
        __typename
        ... on ProductVariant {
          id
          product {
            id
            registration: metafield(key: "insignia_registration_v2") { value }
            policy: metafield(key: "insignia_policy_v2") { value }
          }
        }
      }
    }
  }
  localization { country { isoCode } language { isoCode } market { id } }
  shop {
    localTime { date }
    publicConfig: metafield(key: "insignia_public_config_v2") { value }
  }
}
